import os
from datetime import datetime
from moler.util.moler_test import MolerTest  # type: ignore
from taf.ul.sc import perf
from taf.ul.sc.perf.tc import tc
from taf.ul.sc.perf.tc.tc_helpers import get_absolute_path
from taf.ul.sc.perf.util.logger import log_info_to_console
from taf.ul.sc.perf.util.test_duration_manager import TestDurationManager
from taf.ul.sc.perf.util.helpers import round_time_to_seconds
from moler.exceptions import CommandFailure, ExecutionException  # type: ignore


def start_scenario():
    scenario_path = get_absolute_path(tc.run_params['scenario_name'])

    perf.tl.ue.copy_scenario_file(source_scenario_path=scenario_path)
    scenario = os.path.basename(scenario_path)

    if perf.tl.ue.is_scenario_running():
        perf.tl.ue.stop_scenario()

    if tc.is_feature_enabled("adjust_start_scenario_time_to_stats_period"):
        sleep_time = _calculate_sleep_time()  # TODO Check if time on VM and BTS is synced. eg via cmd timedatactl
        MolerTest.info(msg="Waiting for beginning of PMstats collecting period.")
        MolerTest.sleep(seconds=sleep_time)
    perf.tl.ue.start_scenario(scenario_name=scenario)
    TestDurationManager().set_execution_start()
    if tc.is_feature_enabled("monitor_cus_syslog") and perf.tl.ue.syslog is not None:
        # sleep for 5 seconds to let scenario start properly
        MolerTest.sleep(seconds=5)
        set_cus_syslog_monitor(scenario)


def set_cus_syslog_monitor(scenario):
    try:
        perf.tl.ue.ws.remove_file(path="/home/cus/cus_syslog_dir")
    except CommandFailure:
        pass
    scenario_name, _ = os.path.splitext(scenario)
    logs_dir = f"{perf.tl.ue.ws.logs_dir}/{scenario_name}/latest"
    perf.tl.ue.ws.create_symbolic_link(link_path="/home/cus/cus_syslog_dir", target_path=logs_dir)
    perf.tl.ue.syslog.connect_to_syslog()
    patterns = tc.run_params["monitor_cus_syslog"]["patterns"]
    till_occurs_times = tc.run_params["monitor_cus_syslog"]["till_occurs_times"]
    break_test = tc.run_params["monitor_cus_syslog"]["break_test"]
    perf.tl.ue.syslog.start_syslog_observer(
        patterns=patterns,
        till_occurs_times=till_occurs_times,
        # + 700 while timeout on executor is 600 so adding some buffer to it
        timeout=tc.run_params['duration'] + 700,
        break_test=break_test,
        break_function=TestDurationManager().break_test
    )


def _calculate_sleep_time():
    period = tc.run_params['adjust_start_scenario_time_to_stats_period']['period']
    offset = abs(tc.run_params['adjust_start_scenario_time_to_stats_period']['offset'])
    current_time = datetime.now()

    next_pm_period = (period - current_time.minute % period) * 60 - current_time.second
    if offset > period:
        sleep_time = next_pm_period
    else:
        sleep_time = next_pm_period - offset * 60
        while sleep_time < 0:
            sleep_time = sleep_time + period * 60

    return sleep_time


def _get_offset():
    period = tc.run_params['adjust_start_scenario_time_to_stats_period']['period']
    offset = tc.run_params['adjust_start_scenario_time_to_stats_period']['offset']
    calculated_offset = 0
    if abs(offset) > period:
        calculated_offset = abs(offset) * 60

    return calculated_offset


def sleep_for_the_rest_of_the_time():
    duration = tc.run_params['duration']
    tdm = TestDurationManager()
    if tc.is_feature_enabled("adjust_start_scenario_time_to_stats_period"):
        offset = _get_offset()
        if offset:
            MolerTest.info("Offset is set. Scenario will be {} seconds longer".format(offset))
        duration = duration + offset

    tdm.calculate_execution_end(seconds=duration)
    execution_end = round_time_to_seconds(datetime.strptime(str(tdm.execution_end), "%Y-%m-%d %H:%M:%S.%f"))
    # stop scenario if execution end time is in the past
    if execution_end <= datetime.now():
        MolerTest.info("Scenario duration time already passed. Stopping scenario.")
        log_info_to_console("Scenario already passed its duration time. Stopping scenario.", log_hierarchy=2)
    else:
        log_info_to_console(msg="Scenario duration [{} seconds]".format(duration), log_hierarchy=2)
        log_info_to_console(msg="Test will be finished at [{}]".format(execution_end), log_hierarchy=2)
        interval = None
        if tc.is_feature_enabled("manual_test_check_interval"):
            interval = tc.run_params['manual_test_check_interval']['check_interval']
        tdm.sleep(seconds=duration, interval=interval)


def wait_for_last_bts_stats():
    if tc.is_feature_enabled("wait_for_last_bts_stats"):
        log_info_to_console(msg="Waiting for last bts stats", log_hierarchy=1)
        events = []
        for bts in tc.required_btss():
            event = bts.start_waiting_for_bts_stats(stats_type=tc.run_params['collect_bts_stats']['type'])
            events.append(event)

        for event in events:
            event.await_done(timeout=15 * 60)


def stop_scenario():
    if tc.is_feature_enabled("monitor_cus_syslog"):
        perf.tl.ue.syslog.stop_syslog_observer()
        events = perf.tl.ue.syslog.get_events()
        for event in events:
            counter = event.counter if hasattr(event, "counter") else 0
            message = "Syslog pattern(s) {} occurred {} time(s)".format(
                            event.detect_patterns,
                            counter)
            # Error if counter is equal or higher than till_occurs_times
            # Warning if counter is lower than till_occurs_times but higher than 0
            if counter >= event.till_occurs_times:
                try:
                    MolerTest.error(msg=message, raise_exception=False)
                except ExecutionException:
                    pass
            else:
                if counter > 0:
                    MolerTest.warning(msg=message)
        try:
            perf.tl.ue.ws.remove_file(path="/home/cus/cus_syslog_dir")
        except CommandFailure:
            pass
    perf.tl.ue.stop_scenario()
